import{_ as l}from"./chunks/CityLink.vue_vue_type_script_setup_true_lang.DYs3D5sh.js";import{o as t,c as a,j as i,a as r,F as e,B as o,b as c,a5 as d}from"./chunks/framework.CnBNXlt7.js";import"./chunks/travelogue.BgrUIWBQ.js";import"./chunks/utils.Crj2JTAd.js";import"./chunks/dayjs.min.DTWwpTri.js";const g="/life/img/trip/log-20250620-01.png",n="/life/img/trip/log-20250620-02.png",u="/life/img/trip/log-20250620-03.png",_="/life/img/trip/log-20250620-04.png",b="/life/img/trip/log-20250620-05.png",k="/life/img/trip/log-20250620-06.png",y="/life/img/trip/log-20250620-07.png",f="/life/img/trip/log-20250620-08.png",h="/life/img/trip/log-20250620-09.png",v="/life/img/trip/log-20250620-10.png",P="/life/img/trip/log-20250620-11.png",q="/life/img/trip/log-20250620-12.png",T="/life/img/trip/log-20250620-13.png",E=JSON.parse('{"title":"梅州河源","description":"","frontmatter":{"city":["梅州","河源"],"date":"2025/06/20"},"headers":[],"relativePath":"trip/travelogue/20250620.md","filePath":"trip/travelogue/20250620.md","lastUpdated":1752763073000}'),B={name:"trip/travelogue/20250620.md"},$=Object.assign(B,{setup(x){return(s,p)=>(t(),a("div",null,[p[0]||(p[0]=i("h1",{id:"梅州河源",tabindex:"-1"},[r("梅州河源 "),i("a",{class:"header-anchor",href:"#梅州河源","aria-label":'Permalink to "梅州河源"'},"​")],-1)),(t(!0),a(e,null,o(s.$frontmatter.city,(m,D)=>(t(),c(l,{city:m,date:new Date(s.$frontmatter.date)},null,8,["city","date"]))),256)),p[1]||(p[1]=d('<h2 id="_2025-06-20-周五-晴转多云-27°-33°" tabindex="-1">2025/06/20 周五 晴转多云 27°-33° <a class="header-anchor" href="#_2025-06-20-周五-晴转多云-27°-33°" aria-label="Permalink to &quot;2025/06/20 周五 晴转多云 27°-33°&quot;">​</a></h2><p>16:14出发，说公交车20分到站，实则16到，还好16已经在了。<br> 还没到地铁站，收到了航变信息，犹豫了一秒钟，还是去机场了。</p><p>人生总是事与愿违。之前每次都赶时间，比如提前两个小时，吃饭就会很赶，这次特意多提前了10分钟。可惜，偏偏这个时候航变延误一个小时。</p><p>贵宾厅慢慢吃饭吧，以为牛肉之类的，没想到是小龙虾。不爱吃，随便吃点。</p><p>18:56提示前序航班落地，现在都这样搞吗？前序航班飞不了，就调整后面航班的时间，就不叫做延误了？太离谱了。</p><p>从18:30起飞改到19:35，再看看变成20:09。</p><p>19:27登机，发现，贵宾安检人非常多，先上个厕所吧。回来还是排队，效率非常低。40才成功登机。过去后继续排队等行李过安检。</p><p>这会儿，幺蛾子又来了，有人行李打火机没检查出来。开始复盘，安检机子也不动了，几个人就硬等他们复盘。也不知道最后找没找到人。</p><p>到达廊桥下面，都没人了。我是最后一个上机的，蛮尴尬的。</p><p>离谱的事情越来越多。19:46，最后一个乘客上来，我还以为我是最后一个。看起来不到10岁，一个人坐飞机。挺牛的。</p><p>20:07顺利起飞。第一次坐巴航，ERJ190，小飞机，起飞噪音只有73dB左右，比平时坐的噪音稍低一点点。后面平飞声音感觉差不多。</p><p>飞机上又有苍蝇，唉。发现了个细节，飞机飞行过程中，总是听到叮咚叮咚的声音，可能是机长在跟乘务员打电话。</p><p>睡了完整的一路，在快下降的时候醒了。</p><p>35成功落地。哦非常小的机场，没有廊桥之类的。看了看地图可以公交车直接到，但是奇怪的设计，没有人行道吗？还是我走错了，走着车行道，走到了大路边。看到很多共享电单车，天气还不错，就决定骑车吧，公交车不一定啥时候来呢。</p><p>看起来很近，4km左右的路，直线，骑了15分钟左右吧。体验有点差，路灯很亮，但是没有非机动车道啊。似乎是与人行道混用，就一直走在最右侧的机动车道，贴着最右边，一路直行。很危险的感觉。</p><p>好不容易经过一段，有非机动车道的路，手都颠麻了，路很不平，猜测可能是少铺了一层。再走一小段，又没有非机动车道了，还是比较危险的。</p><p>顺利抵达酒店，房间窗户却卡不住。又叫了前台，来修理了一下，好在很好修。</p><h2 id="_2025-06-21-阴转小雨-24°-31°-周六" tabindex="-1">2025/06/21 阴转小雨 24°-31° 周六 <a class="header-anchor" href="#_2025-06-21-阴转小雨-24°-31°-周六" aria-label="Permalink to &quot;2025/06/21 阴转小雨 24°-31° 周六&quot;">​</a></h2><p>8点多起来吃个早餐，而后回去简单休整。下楼打算公交车，外面天气刚刚好，早上下过雨了，此时天阴阴。没等两分钟，看了看实时公交，估计等不到。就决定打车前往千佛塔，不知道哪来的券，打车只要1.9元。</p><p>车上路过了一座很大的基督教堂，没来及拍照。很快抵达目的地，非常晒，地上的雨水已经快要干掉了。</p><p>寺庙很大，慢慢逛吧，大家每一个佛都会点柱香拜一拜，我就拍拍照，看看细节。非常壮观，很多雕塑，耀眼的琉璃瓦，好似皇家寺庙。</p><p>降龙观音面对着一个巨大的广场，伫立着六根巨龙盘绕的柱子。继续往上走，一口两三米高的大鼎压在祖师殿下。</p><p>再往上，看到观世音菩萨，后面的石堆上一只小猫咪在四处探索。</p><p>再往上走到了 千佛塔跟前，可惜从09年开始就不能前往塔顶了。</p><p>参观完毕，路过水龙头 洗把脸</p><p>往下走观世音菩萨前面，非常光滑，一是刚下过雨，二是少有人来，两次差点滑倒。看到一只龟和几条大鱼<br> 太高了，看不到最上面的小猫咪了</p><p>没有力气再上去了，就出去了</p><p>看了看下一站距离，很近，就骑电瓶车前往。</p><p>唯有一辆太阳下暴晒且没有遮阳垫子的车，屁股烫掉。</p><p>路过了教堂，在外面拍了照片</p><p>路上很晒</p><p>原本目的地是东山书院，但是客家博物馆更近，就先去博物馆了</p><p>走马观花式参观完毕，又把附近的几幢特色楼观赏了一番。</p><p>还有人在这里开直播</p><p>转而去东山书院，已是12点，说关门了，下午两点才开门</p><p>直接回去吧，旁边还有人拍婚纱照</p><p>骑车前往江北老街，刚开始走错了，在江边绕了个来回，</p><details class="details custom-block"><summary>12:14-12:29 3.49km</summary><p><img src="'+g+'" alt="img"></p></details><p>感觉这个特色街，基本都闭店了。也没什么人，太阳也挺晒的。拉倒吧，打车去吃面，新宜家面馆。</p><details class="details custom-block"><summary>菜单</summary><p><img src="'+n+'" alt="img"></p></details><p>三及第不知道是什么，赶快搜了一下，还好提前搜了，有猪肝什么的。根本不吃。点了牛肉汤枸杞叶+腌面，非常好吃的呀。</p><details class="details custom-block"><summary>美食</summary><p><img src="'+u+'" alt="img"></p></details><p>吃完感觉还差点，又点了一份腌粉，不太行，细细的粉丝原本就不爱吃，再加上可能饱了已经。</p><p>全部吃完，就骑车回来了。</p><p>实在太热了外面，休息到五六点钟才出门。骑车前往金苑酒家。看了推荐菜：石墨酿豆腐，客家古法盐焗鸡，经典醋香拌牛肉。鸡太贵，估计也吃不完，就点了豆腐和牛肉。牛肉73，豆腐30。看了美团梅菜包子，4个5块，就又买了一份。好评送扇子+冰粥，直接白嫖。结算105，100买95折95块，再付5块，实付100。很好吃的。</p><details class="details custom-block"><summary>美食</summary><p><img src="'+_+'" alt="img"></p></details><p>而后骑车去客家小镇，看来看去咋感觉很坑啊。夜游票40块，搭的人工景，就一些彩灯，糊弄鬼呢。游客中心表示，晚上不能登山，一片乌漆嘛黑，直接溜了，一分不花。</p><details class="details custom-block"><summary>19:00-19:12 2.83km</summary><p><img src="'+b+'" alt="img"></p></details><p>再去泮坑，一路非常黢黑，进村了属于是。刚停车，就看到有一对想走，但是缺一辆车，就把我刚锁的车骑走了。</p><details class="details custom-block"><summary>19:31-19:44 3.18km</summary><p><img src="'+k+'" alt="img"></p></details><p>四处都挺黑的，也就路灯还挺亮。看了步行道，上面提示绕坑一周只有2.5km。走走看吧，走了50分钟吧</p><p>隔一个亭子就有人k歌，唱的比较难听 似乎都是开车来的</p><p>走到起点，果不其然，过来没车骑了</p><details class="details custom-block"><summary>19:45-20:35 3.5km</summary><p><img src="'+y+'" alt="img"></p></details><p>走到最近的车附近，走路比骑车更危险了，骑车走的是机动车道，来回双车道。人也得走这个道，没别的地方走。</p><p>开车</p><details class="details custom-block"><summary>20:35-20:47 2.7km</summary><p><img src="'+f+'" alt="img"></p></details><p>因为买的电单车卡只能抵扣3块，按计费规则就是免费15分钟，看了看到酒店的距离，15分钟不得行。正好路过万达，去优衣库看看衣服裤子。速干裤依然没有。看了看几个外套样子的短袖，买了一件。斜挎包也不错，79很便宜，买了，容量也很大。 其他看中的网上买吧，省的多拿东西。</p><p>买完回酒店了。</p><h2 id="_2025-06-22-周日-晴转多云-24°-33°" tabindex="-1">2025/06/22 周日 晴转多云 24°-33° <a class="header-anchor" href="#_2025-06-22-周日-晴转多云-24°-33°" aria-label="Permalink to &quot;2025/06/22 周日 晴转多云 24°-33°&quot;">​</a></h2><p>河源天气看起来比梅州凉快。实际差不多。25°-32°，但是下午，后面下雨之后舒服极了</p><div class="tip custom-block"><p class="custom-block-title">计划去河源</p><p>09:58-11:07 梅州西-河源东 D7351 1h9m ¥81<br> 19:43-20:49 河源东-梅州西 D7348 1h6m ¥81<br> 东站f5去太平街<br> 晚上看看梅江边</p></div><p>8:30酒店吃完饭，简单休整一下<br> 9点出门打车，很快，不到20分钟吧，20块，提前半个小时到高铁站</p><p>梅州西停那么远，进站走很远<br> 河源东也停那么远，就不能停到出站口吗，走了完整的站台，从最南走到最北，最北出站口，绝了。</p><details class="details custom-block"><summary>路景</summary><p><img src="'+h+'" alt="img"></p></details><p>慢悠悠上个厕所，出来正好F5就在路边，票价4块的公交车，除了座椅和大巴座椅一样，其他都是公交车的样貌。4块也许是快速车的缘故，比普通公交车贵2块。</p><p>28左右开出，路面是混凝土不是柏油路，跟hk 差不多，但是很颠，毕竟是公交车。需要提前按铃，不按不停。46抵达，过个天桥晒死，天桥看不到下面，全部遮起来了，莫名其妙。</p><p>大部分都有阴凉的地方很舒服，比梅州凉快了很多。</p><p>这天气太舒服了，吹着凉风，蓝天白云湖面荡漾，更重要的是几乎没人。 似乎没有榕树了，旁边种的树都又大又遮阴还不会破坏路面，非常好</p><details class="details custom-block"><summary>11:54-12:33 1.93km</summary><p><img src="'+v+'" alt="img"></p></details><details class="details custom-block"><summary>美景</summary><p><img src="'+P+'" alt="img"></p></details><p>饭吃着非常不错，怡鑫鹏早餐，花旗汤入口微苦而后回甜</p><details class="details custom-block"><summary>美食</summary><p><img src="'+q+'" alt="img"></p></details><p>吃完去博物馆吧 太阳时有时无，我也在街道的两边来回穿梭，哪里凉快走哪里。街道上没什么人，大家都午休了吗？ 还是很热的外面</p><p>爽死了，来博物馆</p><p>一楼参观完毕 准备电梯二楼 看到有个小馆 也太神奇了 南阳馆</p><p>比较小 半个小时逛完 14:00 外面凳子上歇息一下</p><p>歇了半个小时 在出门去龟峰山 感觉有点没有力气 气血不足了</p><p>看着越来越喘不上气 仿佛被什么东西压着一般 呼吸很重 果然大雨来袭 一切得到释放 在淋雨前 赶快跑进恐龙博物馆</p><p>很多恐龙蛋，娃也很多，各种科普知识 还有昆虫标本展，非常多的昆虫，拍了很多照片 16:00 参观完毕 雨也停了 太爽了这天气</p><p>可惜时间没规划好，农夫山泉下班了</p><p>去图书馆 就是客家中心<br> 想等公交车 113、118看起来等不到了，打车吧，10块钱</p><p>打车路上 看了看到东站坐F2，预计去儿童公园站点坐 开逛</p><p>这图书馆的景色真不错，外面这么大个池塘</p><p>从图书馆简单逛逛出来，外面又有人在唱歌，这里的人真挺喜欢唱歌的整个音响，整个话筒</p><p>简单逛完 看看小瀑布</p><p>骑车去吃粉</p><p>很饿，猪脚很好吃 粉不行 避雷</p><p>去万隆城坐F2吧，骑车过来发现</p><p>两个小时一班，完了 想骑电车过去，发现东站不在运营区，笑死 看看打车吧</p><p>打车20多块，顺风车10块，看看能不能顺风车 等了10多分钟，司机一直不出发 想着等到40再不来就打车 40已到，秒接单。直接取消顺风车 打车去东站了。 20分钟就到了 提前了40多分钟 没水喝了 来便利店看看 写着那么大的字“平价水” 实际1块的水卖3块 笑死 溜了溜了</p><p>绝了到站梅州西也是停这么远，哈哈</p><p>拉客的有点太多了，都想上手很烦</p><p>16停车，正好7路到了，我给司机招手 没停 继续坐着等车 发现可能需要招手才停，因为5路路过，没停 就得仔细看了 35来车了，站起来，司机远光闪了一下，我也招手了，车上没人 也是皮座，跟大巴一样 全程都没人上车呀</p><p>路过梅江很好看，想去江边看看 到地方下车 骑电动车去江边 拍了拍照片 就回酒店了</p><p>因为晚饭太难吃 看到楼下有粉 就想尝试一下 但是计划回酒店去洗衣服 先回酒店洗衣房看了看 就不想洗了 直接下楼吃饭吧</p><h2 id="_2025-06-23-晴-周一-25°-34°" tabindex="-1">2025/06/23 晴 周一 25°-34° <a class="header-anchor" href="#_2025-06-23-晴-周一-25°-34°" aria-label="Permalink to &quot;2025/06/23 晴 周一 25°-34°&quot;">​</a></h2><p>按计划，今天早起去书院，而后随便看看那个学宫。<br> 7:30起床，印象中按了再睡一会，其实把闹钟关掉了。还好突然有通知消息，不然直接睡过去就完了。<br> 起来洗刷一下，直接带好东西，去酒店吃早餐。今天吃了酒店的腌面，不好吃，相比外面的。吃完，就直接骑车去东山书院，8:30到书院，骑了12分钟左右。<br> 除了老建筑外，也可能是重修的，没什么看头儿，就正堂二堂，二楼正堂，及三楼祭拜的地方开放。所有偏房全部关闭，可参观性较差。买了俩冰箱贴，就走了。<br> 骑车去学宫。</p><details class="details custom-block"><summary>08:52-09:24 4.71km</summary><p><img src="'+T+'" alt="img"></p></details><p>更是没啥看的，门口看起来就一般，周一正好也闭馆。直接回去了，热的不行，江边拍了拍照。到酒店9:30。</p><p>10点官方发布了高温预警。也没啥可逛的了，躺着休息吧。没多久就收到了航变延误通知，唉。</p><div class="warning custom-block"><p class="custom-block-title">什么逆天航变</p><p>原定15:30-17:20<br> 6.9因公司原因变更为15:50-17:35<br> 6.23因空域活动变更为16:40-18:25</p></div><p>什么空域活动，根本就是航班安排过于密集，前序一个延误，后面全部跟着倒霉。</p><p>中午，外面实在太热，就想看看外卖如何。一个拌粉9块，一个腌面+牛肉枸杞叶汤17块，菠菜腌面不错，汤也不错。拌粉还送了鸡蛋汤，鸡蛋肉饼里面，很值，很不错。</p><p>吃完，航变没办法问问酒店能不能三点退房，酒店接受了。</p><p>15:10退房，公交过去，一路没啥人上下车，下车需要提前告知司机。10分钟就到了，看着手机提醒还会继续延误，就不想安检，在外面坐着喝水，玩手机。</p><p>喝的差不多了，进去慢慢等吧。17:00左右终于登机。</p><p>17:26顺利起飞，爬升阶段只有72dB。20分钟左右，就平飞了，乘务员给每人发了一瓶水。这点比首都航空好太多。</p><p>18:50 稳稳落地，很快19:00就下机了。今天下机没什么人，可能天气原因。马不停蹄，T3，15分钟能走到地铁口，</p>',109))]))}});export{E as __pageData,$ as default};
